[standards/technology/nodejs/STD-TEC-NODE-005-testing.md#73-prototype-pollution-mitigation-tests]

### 7.3 Prototype Pollution Mitigation Tests

Verify that the prototype pollution controls from STD-TEC-NODE-001 §5 function correctly:

```typescript
describe('Prototype pollution prevention', () => {
  it('rejects JSON body containing __proto__ key', async () => {
    await request(app)
      .post('/api/members')
      .set('Content-Type', 'application/json')
      .send('{"__proto__": {"isAdmin": true}, "memberId": "abc", "planCode": "P1", "dateOfBirth": "1980-01-01"}')
      .set('Authorization', `Bearer ${validToken}`)
      .expect(400);

    // Confirm Object.prototype was not polluted
    expect((Object.prototype as Record<string, unknown>)['isAdmin']).toBeUndefined();
  });

  it('rejects JSON body containing constructor.prototype', async () => {
    await request(app)
      .post('/api/members')
      .set('Content-Type', 'application/json')
      .send('{"constructor": {"prototype": {"isAdmin": true}}}')
      .set('Authorization', `Bearer ${validToken}`)
      .expect(400);
  });
});
```

